void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float t = iTime;
    float aspect_ratio = iResolution.x / iResolution.y;

    float r = 0.35;

    // figure out iteration based on delta Y
    float delta_y = 0.1;  // change in y per second
    float offset_y = 0.1;  // buffer for looping
    float bubble_height = 1.0 + 2.0*r + 2.0*offset_y;
    float frames_per_iteration = bubble_height / delta_y;
    // TODO this seems off
    float iteration = floor(t / frames_per_iteration);
    //float y = 

    // TODO for loop for multiple bubbles?

    float x = 0.5 + sin(iteration * 13.5 + 137.5)*0.125;
    //x += sin(t + 123.1 + cos(t*0.1)*0.25)*0.07;
    //x = mod(x, 0.3) + 0.35;
    float y = t*delta_y + sin(t*1.5)*0.05;
    y = mod(y, bubble_height) - (r + offset_y);

    x += sin(t)*0.05;

    r *= 0.95 + cos(t*1.5)*0.05;

    // set to true to enable debug position and scale of bubble
    if (false) {
        x = 0.5;
        y = 0.5;
        r = 0.35;
    }

    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    float pixel_width = iResolution.x * 0.01;
    vec2 pixelCoord = floor(fragCoord / pixel_width) * pixel_width;
    vec2 pixel_uv = pixelCoord/iResolution.xy;

    uv.x *= aspect_ratio;
    pixel_uv.x *= aspect_ratio;

    // wave distortions
    float wave_d = sin(uv.y*7.0 + t*0.5 + uv.x*0.3)*0.01;
    uv.x += wave_d;

    // color parms
    float color_lerp = 0.0;
    // 1 = full color, 0 = white
    float saturation = 1.0;
    float value = 1.0;
    bool inside_bubble = false;
    bool inside_seaweed = false;

    // check if inside ~bubble~
    x *= aspect_ratio;
    float d = (uv.x-x)*(uv.x-x) + (uv.y-y)*(uv.y-y);
    float r2 = r*r;
    if (d < r2) {
        inside_bubble = true;

        // calc color bubble interior
        //color_lerp = 1.0;
        float pixel_d = (pixel_uv.x-x)*(pixel_uv.x-x) + (pixel_uv.y-y)*(pixel_uv.y-y);
        saturation = 1.0 - pow((pixel_d / r2), 4.0)*0.75;

        // spec highlight
        float offset = 0.5 * r;
        float tr2 = (r*0.7)*(r*0.7);
        float tx = x + offset;
        float ty = y + offset;

        float rot = cos(t*2.0)*0.25;
        tx -= x;
        ty -= y;
        float temp = tx*cos(rot) - ty*sin(rot);
        ty = tx*sin(rot) + ty*cos(rot);
        tx = temp + x;
        ty += y;
        float td = (pixel_uv.x-tx)*(pixel_uv.x-tx) + (pixel_uv.y-ty)*(pixel_uv.y-ty);
        if (td < tr2) {
            float b = 0.9;
            float t_saturation = (1.0-pow(1.0-(td / tr2), 7.5)*b) + (1.0-b);
            saturation = min(saturation, t_saturation);
        }

        // check if within the outline
        if ((r2 - d) < (r*0.01)) {
            value = 0.0;
        }
    }

    // Calc new pixelated uvs
    pixel_width = iResolution.x * 0.005;
    pixelCoord = floor(fragCoord / pixel_width) * pixel_width;
    pixel_uv = pixelCoord/iResolution.xy;

    // refract UVs by the bubble
    r2 = (r*1.2)*(r*1.2);
    if (d < r2) {
        float amp = 1.0 - (r2-d);
        amp *= amp;
        amp = 1.0 - amp;
        amp *= 0.2;
        pixel_uv.x -= amp * (uv.x-x)/r;
        pixel_uv.y -= amp * (uv.y-y)/r;
    }

    // check for seaweed
    float num_s = 32.0;
    float inv_s = 1.0 / num_s;
    float w = 0.1;  // seaweed width in screen space
    for (float i = 0.0; i < num_s; i++) {
        // calc seaweed center x
        x = inv_s * (i+0.5);
        y = pixel_uv.y;
        x += sin(y*5.0 + cos(i*124.27 + t*0.1)*5.0 + t)*0.015;
        x += sin(y*50.0 + cos(i*23.0 + t*0.2)*50.0)*0.002;
        //x += sin(i*123.7 + 13.127 + sin(t*0.025 + i*234.7)*cos(i*123.0)*17.0)*0.1*y;
        y = pow(pixel_uv.y, 2.0);
        y *= sin(i*57.7)*0.5 + 1.5;
        d = abs(pixel_uv.x - x);

        // seaweed vein
        float vein = d*2.0/w;
        vein = (cos(vein*(12.5 + sin(i*123.0 + cos(y*25.0)*2.5)*2.5)))*0.5 + 0.5;
        //vein *= vein * vein;
        vein = 1.0 - vein;
        // vein is now 0 - 1
        // fade out vein, by y
        float vein_y = min((y*0.5) + 0.65, 1.0);
        vein = 1.0 - ((1.0-vein)*(1.0-vein_y));
        float vein_amp = 0.15;
        vein = (vein*vein_amp) + (1.0-vein_amp);

        // check if inside blade of seaweed
        if (d < (w*(1.0-y)*0.5)) {

            // calc if this is a "foreground" blade
            bool is_fg = cos(i*173.115) > 0.5;

            if (is_fg) {
                // special case for the outline
                /*if (value <= 0.001) {
                    //saturation = 0.25;
                    //color_lerp = 0.0;
                    //saturation = 0.0;
                    //value = 0.2;
                }*/
                if (inside_bubble) {
                    value = 0.725;
                }
                else {
                    value = 0.7;
                }

                color_lerp = 2.0 + sin(i*121.2)*2.0 - uv.y*5.0 + (sin(uv.x*450.0)*0.05);
                value *= 0.9 * vein;
                saturation = 1.0;
            }
            else if (!inside_seaweed) {
                if (inside_bubble) {
                    //value *= 0.95;
                    //saturation *= 0.9;
                }
                else {
                    //value *= 0.7;
                    value = 0.7 * vein;
                    saturation = 0.8;
                    color_lerp = 2.5 + sin(i*121.2)*2.0 * uv.y*2.0;
                }
            }

            inside_seaweed = true;
        }
    }

    // background
    if (!inside_bubble && !inside_seaweed) {
        value = (uv.y)*0.65 + 0.25;
        color_lerp += uv.y;
    }

    // light rays
    if (uv.x < (uv.y*0.2)) {
        // todo alternate value
        //saturation = 1.0 - value;
    }

    // assign color
    color_lerp = sin(color_lerp)*0.5 + 0.5;
    vec3 col = color_lerp*vec3(0.7, 0.9, 1.0) + (1.0-color_lerp)*vec3(0.7, 0.7, 1.0);

    // adjust saturation
    col = saturation*col + vec3(1.0-saturation);

    // adjust value
    col *= value;

    // Output to screen
    fragColor = vec4(col,1.0);
}
